import {
  PlaneGeometry,
  MeshBasicNodeMaterial,
  Mesh,
  DoubleSide,
  Object3D,
  TextureLoader
} from 'three/webgpu';

export default function createNode(config, ctx) {
  // Destructure config
  const { assets, scenePosition, cinematicPrimitives } = config;
  const { imageUrl } = assets;

  // Load texture via context loader
  const texture = ctx.textureLoader.load(imageUrl);
  texture.colorSpace = 'srgb'; // Ensure correct color space

  // Create geometry (aspect ratio from source rect: 512/320 ≈ 1.6)
  const geometry = new PlaneGeometry(1.6, 1.0);
  geometry.translate(0, 0, 0);

  // Material – MeshBasicNodeMaterial for unlit look
  const material = new MeshBasicNodeMaterial({
    map: texture,
    side: DoubleSide, // visible from both sides if needed
    transparent: false,
    depthWrite: true
  });

  // Mesh
  const mesh = new Mesh(geometry, material);
  mesh.position.set(
    scenePosition.x || 0,
    scenePosition.y || -0.3,
    scenePosition.z || 0
  );
  mesh.rotation.set(
    scenePosition.rotationX || 0,
    scenePosition.rotationY || 0,
    scenePosition.rotationZ || 0
  );
  mesh.scale.set(
    scenePosition.scaleX || 1,
    scenePosition.scaleY || 1,
    scenePosition.scaleZ || 1
  );

  // User data for cleanup and handlers
  mesh.userData = {
    handlers: {}, // No interactions defined
    cleanup: () => {
      texture.dispose();
      material.dispose();
      geometry.dispose();
      // No GSAP timelines to kill
    }
  };

  return mesh;
}
